from fastapi import FastAPI, HTTPException from fastapi.responses import StreamingResponse from models import ReportData from generators.ppt_builder import PowerPointBuilder import logging
app = FastAPI(title="PowerPoint Report Generator")
logging.basicConfig(level=logging.INFO) logger = logging.getLogger(__name__)
@app.get("/health") async def health_check(): """Health check endpoint""" return {"status": "healthy", "service": "ppt-generator"}
@app.post("/generate-report") async def generate_report(data: ReportData): """ PowerPoint raporu oluştur """ try: logger.info(f"Generating report: {data.title}")
builder = PowerPointBuilder() ppt_buffer = builder.build(data)
filename = f"report_{data.filters.start_date or 'all'}.pptx"
return StreamingResponse( ppt_buffer, media_type="application/vnd.openxmlformats-officedocument.presentationml.presentation", headers={"Content-Disposition": f"attachment; filename={filename}"} )
except Exception as e: logger.error(f"Report generation failed: {e}") raise HTTPException(status_code=500, detail=str(e))
if __name__ == "__main__": import uvicorn uvicorn.run(app, host="0.0.0.0", port=8001)

using System.Net.Http.Json;

// YENİ METOD
public async Task<byte[]> GeneratePowerPointReportAsync(ReportFilterDto filter)
{
    // Dashboard'dan veri al
    var dashboardService = new DashboardService(_evaluationRepository);
    var stats = await dashboardService.GetAdminDashboardAsync(
        filter.StartDate,
        filter.EndDate
    );

    // Python servisi için payload hazırla
    var reportData = new
    {
        title = "Gizli Müşteri Değerlendirme Raporu",
        subtitle = "Performans Analizi ve Şube Karşılaştırması",
        date_range = $"{filter.StartDate?.ToString("dd/MM/yyyy") ?? "Başlangıç"} - {filter.EndDate?.ToString("dd/MM/yyyy") ?? "Bitiş"}",
        total_evaluations = stats.TotalEvaluations,
        average_score = (double)stats.AverageScore,
        top_branches = stats.TopBranches.Select(b => new
        {
            branch_name = b.BranchName,
            average_score = (double)b.AverageScore,
            evaluation_count = b.EvaluationCount,
            region = ""
        }).ToList(),
        bottom_branches = stats.BottomBranches.Select(b => new
        {
            branch_name = b.BranchName,
            average_score = (double)b.AverageScore,
            evaluation_count = b.EvaluationCount,
            region = ""
        }).ToList(),
        monthly_trends = stats.MonthlyTrends.Select(t => new
        {
            year = t.Year,
            month = t.Month,
            month_name = t.MonthName,
            average_score = (double)t.AverageScore,
            evaluation_count = t.EvaluationCount
        }).ToList(),
        branch_comparisons = stats.BranchComparisons.Select(b => new
        {
            branch_name = b.BranchName,
            average_score = (double)b.AverageScore,
            evaluation_count = b.EvaluationCount,
            region = b.Region
        }).ToList(),
        filters = filter
    };

    // Python mikro servisini çağır
    var pythonServiceUrl = _configuration["PythonServices:PptGenerator:Url"] ?? "http://localhost:8001";
    using var httpClient = new HttpClient();
    httpClient.Timeout = TimeSpan.FromMinutes(5);  // Büyük raporlar için timeout artır

    var response = await httpClient.PostAsJsonAsync(
        $"{pythonServiceUrl}/generate-report",
        reportData
    );

    if (!response.IsSuccessStatusCode)
    {
        var error = await response.Content.ReadAsStringAsync();
        throw new Exception($"PowerPoint generation failed: {error}");
    }

    return await response.Content.ReadAsByteArrayAsync();
}

[HttpPost("powerpoint")]
public async Task<IActionResult> GeneratePowerPointReport([FromBody] ReportFilterDto filter)
{
    try
    {
        var pptBytes = await _reportService.GeneratePowerPointReportAsync(filter);

        var fileName = $"report_{DateTime.UtcNow:yyyyMMdd_HHmmss}.pptx";

        return File(
            pptBytes,
            "application/vnd.openxmlformats-officedocument.presentationml.presentation",
            fileName
        );
    }
    catch (Exception ex)
    {
        return StatusCode(500, new { message = ex.Message });
    }
}
